1177	+describe("triggers out of type order in one step, with contested sectors", () => {
1178	+  // As above, and A carries a tide of their own, which F steals at START + 110.
1179	+  const players = { A: S[4], B: S[0], C: S[2], D: S[6], E: S[8], F: S[5] };
